 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    seen = set()
    frames = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if not color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and g[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0, r1 = min(y for y, x in comp), max(y for y, x in comp)
            c0, c1 = min(x for y, x in comp), max(x for y, x in comp)
            if r1-r0 >= 2 and c1-c0 >= 2:
                boundary = {(y, x) for y in range(r0, r1+1) for x in range(c0, c1+1)
                            if y in (r0, r1) or x in (c0, c1)}
                if set(comp) == boundary:
                    frames.append((r0, r1, c0, c1, color))

    frame_cells = set()
    for r0, r1, c0, c1, color in frames:
        frame_cells.update((r, c) for r in range(r0, r1+1) for c in range(c0, c1+1)
                           if r in (r0, r1) or c in (c0, c1))

    counts = Counter(g[r][c] for r in range(h) for c in range(w)
                     if g[r][c] and (r, c) not in frame_cells)
    out = [[0 for _ in range(w)] for _ in range(h)]
    for r0, r1, c0, c1, color in frames:
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                if r in (r0, r1) or c in (c0, c1):
                    out[r][c] = color
        ih, iw = r1-r0-1, c1-c0-1
        needed = (ih*iw + 1)//2
        matches = [v for v, n in counts.items() if n == needed]
        if len(matches) == 1:
            fill = matches[0]
            for r in range(r0+1, r1):
                for c in range(c0+1, c1):
                    if ((r-r0-1) + (c-c0-1)) % 2 == 0:
                        out[r][c] = fill
    return out
